   page.evaluate('blocked=true');page.locator('#game').focus();before=page.evaluate('attempts.length');page.keyboard.press('z');assert page.evaluate('attempts.length')==before;assert panel.is_hidden();page.evaluate('blocked=false;reset(15)');page.wait_for_timeout(40);results['blockedMenuKeysUntouched']=True
