   page.evaluate('binding.dispose();binding.dispose()');assert panel.count()==0;assert page.evaluate('frees')==1;before=page.evaluate('polls');page.wait_for_timeout(50);assert page.evaluate('polls')==before;results['idempotentDisposeFreesAndStopsPolling']=True
   mobile=browser.new_page(has_touch=True,viewport={'width':390,'height':844});mobile.goto(url);mobile.wait_for_function('ready');assert mobile.evaluate('navigator.maxTouchPoints')>0;assert mobile.evaluate('document.activeElement.tagName')!='INPUT';mobile.locator('[data-name]').tap();mobile.keyboard.press('End');mobile.keyboard.type('XY');assert mobile.locator('[data-name]').input_value()=='REDXY';assert mobile.evaluate('writes.at(-1)[4]')=='REDXY';results['mobileTapFocusAndTyping']=True
   print(json.dumps(results,indent=2));browser.close();assert all(results.values()), 'Failed expectations: '+', '.join(k for k,v in results.items() if not v)
